package com.adc.application;

import com.adc.domain.appointmentbooking.AppointmentBookingRules;
import com.adc.domain.patients.PatientRules;
import com.adc.domain.shared.*;
import com.adc.identity.IdentityGate;
import com.adc.infrastructure.*;
import java.time.*;
import java.util.*;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.json.JsonMapper;

@Service @Transactional(isolation=Isolation.READ_COMMITTED,rollbackFor=Exception.class)
public class PatientBillingService implements ReceiptPolicy {
    private static final JsonMapper JSON=JsonMapper.builder().build();
    private final PatientStore patients;private final AtomicCommandExecutor commands;private final IdentityGate gate;private final PatientBillingStore ledger;private final AppointmentBookingService booking;private final AppointmentBookingStore appointments;private final ScheduleStore schedules;private final BusinessRowLocks locks;private final Clock clock;private final Environment environment;private final AuditWriter audit;
    public PatientBillingService(AtomicCommandExecutor commands,IdentityGate gate,PatientBillingStore ledger,AppointmentBookingService booking,AppointmentBookingStore appointments,ScheduleStore schedules,BusinessRowLocks locks,Clock clock,Environment environment,AuditWriter audit,PatientStore patients){this.patients=patients;this.commands=commands;this.gate=gate;this.ledger=ledger;this.booking=booking;this.appointments=appointments;this.schedules=schedules;this.locks=locks;this.clock=clock;this.environment=environment;this.audit=audit;}
    private byte[] confirmation(long patient){var current=patients.view(patient);var facts=new LinkedHashMap<String,Object>();for(String field:List.of("full_name","date_of_birth","phone","billing_address","email","emergency_contact_name","emergency_contact_phone","allergy_confirmation_reference","allergy_review_status"))facts.put(field,current.get(field));return Crypto.sha256(CanonicalJson.normalize(JSON.writeValueAsString(facts)));}
    private boolean demo(long clinic){return environment.getProperty("adc.demo-payments.enabled",Boolean.class,false)&&Arrays.stream(environment.getProperty("adc.demo-payments.clinics","").split(",")).map(String::trim).filter(s->!s.isEmpty()).anyMatch(ledger.clinicCode(clinic)::equals);}
    private void requireDemo(long clinic){if(!demo(clinic))throw new DomainFailure(409,"DEMO_PAYMENT_DISABLED");}
    private List<Long> staff(IdentityGate.Identity actor,String cap){var scope=new TreeSet<Long>();for(String role:List.of("CASHIER","HEADQUARTERS"))try{scope.addAll(gate.staffClinics(actor,role,cap));}catch(DomainFailure denied){if(denied.status()!=403)throw denied;}if(scope.isEmpty())throw new DomainFailure(403,"ACCESS_DENIED");return List.copyOf(scope);}
    private void access(IdentityGate.Identity actor,long id,boolean refund){
        if(actor.subjectType().equals("PATIENT")){
            gate.requirePatient(actor,appointments.bound(actor.subjectId()));
            var b=ledger.bill(id,false);gate.requirePatient(actor,b.patient());
            if(refund&&!b.kind().equals("REGISTRATION"))throw new DomainFailure(403,"ACCESS_DENIED");
        }else{
            var scopes=staff(actor,refund?"billing.refund":"billing.read");
            if(!scopes.contains(ledger.bill(id,false).clinic()))throw new DomainFailure(403,"ACCESS_DENIED");
        }
    }
    private void payAccess(IdentityGate.Identity actor,long id){access(actor,id,false);if(!actor.subjectType().equals("PATIENT")&&!staff(actor,"billing.pay").contains(ledger.bill(id,false).clinic()))throw new DomainFailure(403,"ACCESS_DENIED");}
    private BusinessRowLocks.Plan billPlan(long id){var hint=ledger.bill(id,false);if(hint.hold()!=null){var h=ledger.hold(hint.hold());return new BusinessRowLocks.Plan(Set.of(h.dentist()),Set.of(h.schedule()),hint.appointment()==null?Set.of():Set.of(hint.appointment()));}if(hint.appointment()!=null){var a=appointments.view(hint.appointment());return new BusinessRowLocks.Plan(Set.of(Long.parseLong((String)a.get("dentist_id"))),Set.of(Long.parseLong((String)a.get("schedule_id"))),Set.of(hint.appointment()));}return new BusinessRowLocks.Plan(Set.of(),Set.of(),Set.of());}
    private PatientBillingStore.Bill lock(long id){var plan=billPlan(id);locks.acquire(plan);var bill=ledger.bill(id,true);plan.verifyUnchanged(billPlan(id));return bill;}
    private AtomicCommandExecutor.Result result(long id){var b=ledger.bill(id,false);return new AtomicCommandExecutor.Result(JSON.writeValueAsString(List.of("PatientBill:"+id)),JSON.writeValueAsString(Map.of("bill_id",Long.toString(id))),200,"PatientBill",Long.toString(id),List.of(b.clinic()));}
    private Map<String,Object> resolve(AtomicCommandExecutor.Command command,AtomicCommandExecutor.Result result){long id=Long.parseLong(JSON.readTree(result.summary()).get("bill_id").asText());access(gate.authenticate(command.token(),command.client()),id,false);return view(id);}
    private void expire(PatientBillingStore.Bill b){if(b.hold()!=null&&b.status().equals("PENDING")&&!ledger.hold(b.hold()).expires().isAfter(clock.instant()))ledger.close(b,"EXPIRED");}
    private Map<String,Object> view(long id){var b=ledger.bill(id,false);var row=ledger.view(id);row.put("demo_enabled",demo(b.clinic()));row.put("can_refund",b.kind().equals("REGISTRATION")&&b.appointment()!=null&&ledger.cancelled(b.appointment())&&b.status().equals("PAID"));return row;}
    public Map<String,Object> hold(AtomicCommandExecutor.Command command,AppointmentBookingService.Creation input)throws Exception{
        var result=commands.execute(command,actor->{if(!actor.subjectType().equals("PATIENT"))throw new DomainFailure(403,"ACCESS_DENIED");gate.requirePatient(actor,appointments.bound(actor.subjectId()));},actor->{var valid=booking.validate(actor,input);requireDemo(input.clinic());long amount=appointments.registrationFee(input.clinic(),valid.schedule().dentist());if(amount<=0)throw new DomainFailure(409,"FREE_BOOKING_REQUIRED");if(appointments.occupied(valid.schedule().dentist(),input.at(),valid.schedule().slot()))throw new DomainFailure(409,"SLOT_OCCUPIED");return result(ledger.createHold(valid.patient(),valid.schedule(),input.at(),input.treatments(),confirmation(valid.patient()),amount));});return resolve(command,result);
    }
    public Map<String,Object> pay(AtomicCommandExecutor.Command command,long id)throws Exception{
        var result=commands.execute(command,actor->payAccess(actor,id),actor->{var b=lock(id);payAccess(actor,id);requireDemo(b.clinic());if(b.status().equals("PAID")||b.status().equals("REFUNDED"))return result(id);if(!b.status().equals("PENDING"))return result(id);expire(b);b=ledger.bill(id,true);if(!b.status().equals("PENDING"))return result(id);
            Long appointment=null;
            if(b.hold()!=null){var h=ledger.hold(b.hold());patients.lock(b.patient());if(!java.security.MessageDigest.isEqual(h.confirmation(),confirmation(b.patient()))){ledger.close(b,"CLOSED");return result(id);}var s=schedules.get(h.schedule());try{AppointmentBookingRules.slot(s,h.at(),clock.instant());if(s.clinic()!=h.clinic()||s.dentist()!=h.dentist()||s.slot()!=h.minutes())throw new DomainFailure(422,"SCHEDULE_CHANGED");schedules.eligible(s.dentist(),s.clinic(),s.date());appointments.treatments(s.dentist(),s.date(),h.treatments(),true);if(appointments.occupiedExcept(s.dentist(),h.at(),s.slot(),h.id()))throw new DomainFailure(409,"SLOT_OCCUPIED");}catch(DomainFailure invalid){if(invalid.status()!=422&&invalid.status()!=409)throw invalid;ledger.close(b,"CLOSED");return result(id);}appointment=appointments.create(b.patient(),s,h.at(),h.treatments(),actor.subjectType().equals("PATIENT")?"PATIENT":"CASHIER",actor.subjectId(),command.key());}
            ledger.pay(b,appointment);return result(id);});return resolve(command,result);
    }
    public Map<String,Object> close(AtomicCommandExecutor.Command command,long id)throws Exception{var result=commands.execute(command,actor->payAccess(actor,id),actor->{var b=lock(id);payAccess(actor,id);if(b.status().equals("PAID")||b.status().equals("REFUNDED"))throw new DomainFailure(409,"PAID_BILL_CANNOT_CLOSE");if(b.hold()==null)throw new DomainFailure(409,"TREATMENT_BILL_CANNOT_CLOSE");ledger.close(b,"CLOSED");return result(id);});return resolve(command,result);}
    public Map<String,Object> refund(AtomicCommandExecutor.Command command,long id,String reason)throws Exception{var result=commands.execute(command,actor->access(actor,id,true),actor->{var b=lock(id);access(actor,id,true);PatientRules.text(reason,255,false);if(b.status().equals("REFUNDED"))return result(id);if(!b.status().equals("PAID"))throw new DomainFailure(409,"PAID_BILL_REQUIRED");if(b.kind().equals("REGISTRATION")&&(b.appointment()==null||!ledger.cancelled(b.appointment())))throw new DomainFailure(409,"CANCEL_APPOINTMENT_FIRST");ledger.refund(b,actor.subjectId(),reason);return result(id);});return resolve(command,result);}
    public Map<String,Object> get(String token,String client,long id,String request){var actor=gate.authenticate(token,client);access(actor,id,false);var b=lock(id);expire(b);audit.success(actor,"getPatientBill","PatientBill",Long.toString(id),List.of(b.clinic()),request);return view(id);}
    public Map<String,Object> list(String token,String client,String cursor,int limit,String request){var actor=gate.authenticate(token,client);Long patient=null;List<Long> clinics=null;if(actor.subjectType().equals("PATIENT")){patient=appointments.bound(actor.subjectId());gate.requirePatient(actor,patient);}else clinics=staff(actor,"billing.read");if(limit<1||limit>100)throw new DomainFailure(400,"INVALID_REQUEST");var ids=ledger.list(patient,clinics,cursor==null?0:BusinessValues.id(cursor),limit+1);String next=null;if(ids.size()>limit){ids=ids.subList(0,limit);next=Long.toString(ids.getLast());}var plans=new LinkedHashMap<Long,BusinessRowLocks.Plan>();var dentists=new TreeSet<Long>();var schedulesToLock=new TreeSet<Long>();var visits=new TreeSet<Long>();for(long id:ids){var p=billPlan(id);plans.put(id,p);dentists.addAll(p.dentists());schedulesToLock.addAll(p.schedules());visits.addAll(p.appointments());}locks.acquire(new BusinessRowLocks.Plan(dentists,schedulesToLock,visits));var items=new ArrayList<Map<String,Object>>();for(long id:ids){var b=ledger.bill(id,true);plans.get(id).verifyUnchanged(billPlan(id));expire(b);items.add(view(id));}audit.success(actor,"listPatientBills","PatientBill",null,clinics==null?List.of():clinics,request);var page=new LinkedHashMap<String,Object>();page.put("items",items);page.put("next_cursor",next);return page;}
    public Map<String,Object> fee(String token,String client,long clinic,long dentist,String request){var actor=gate.authenticate(token,client);if(!actor.subjectType().equals("PATIENT"))gate.requireStaff(actor,"HEADQUARTERS","resource.read",clinic);audit.success(actor,"getRegistrationFee","RegistrationFeePolicy",Long.toString(dentist),List.of(clinic),request);return Map.of("clinic_id",Long.toString(clinic),"dentist_id",Long.toString(dentist),"amount_fen",appointments.registrationFee(clinic,dentist),"demo_enabled",demo(clinic));}
    public Map<String,Object> setFee(AtomicCommandExecutor.Command command,long clinic,long dentist,long amount)throws Exception{commands.execute(command,actor->gate.requireStaff(actor,"HEADQUARTERS","resource.write",clinic),actor->{if(amount<0||amount>100000000)throw new DomainFailure(422,"INVALID_AMOUNT");if(amount>0)requireDemo(clinic);locks.acquire(new BusinessRowLocks.Plan(Set.of(dentist),Set.of(),Set.of()));schedules.eligible(dentist,clinic,clock.instant().atZone(BusinessTime.ZONE).toLocalDate());ledger.fee(clinic,dentist,amount);return new AtomicCommandExecutor.Result(JSON.writeValueAsString(List.of("RegistrationFeePolicy:"+clinic+":"+dentist)),JSON.writeValueAsString(Map.of("amount_fen",amount)),200,"RegistrationFeePolicy",Long.toString(dentist),List.of(clinic));});return fee(command.token(),command.client(),clinic,dentist,command.requestId());}
    @Override @Transactional(propagation=Propagation.NOT_SUPPORTED)public Set<String> operations(){return Set.of("createBookingHold","payDemoBill","closePatientBill","refundPatientBill","setRegistrationFee");}
    @Override public void authorize(IdentityGate.Identity actor,String operation,String refs){if(!operations().contains(operation))throw new DomainFailure(403,"ACCESS_DENIED");if(refs==null){if(actor.subjectType().equals("PATIENT")){if(operation.equals("setRegistrationFee"))throw new DomainFailure(403,"ACCESS_DENIED");gate.requirePatient(actor,appointments.bound(actor.subjectId()));}else if(operation.equals("setRegistrationFee"))gate.staffClinics(actor,"HEADQUARTERS","resource.write");else if(operation.equals("createBookingHold"))throw new DomainFailure(403,"ACCESS_DENIED");else staff(actor,operation.equals("refundPatientBill")?"billing.refund":"billing.pay");return;}for(var n:JSON.readTree(refs)){String ref=n.asText();if(ref.startsWith("PatientBill:")){long id=Long.parseLong(ref.substring(12));if(operation.equals("payDemoBill")||operation.equals("closePatientBill"))payAccess(actor,id);else access(actor,id,operation.equals("refundPatientBill"));}else if(ref.startsWith("RegistrationFeePolicy:")&&operation.equals("setRegistrationFee"))gate.requireStaff(actor,"HEADQUARTERS","resource.write",Long.parseLong(ref.split(":")[1]));else throw new DomainFailure(403,"ACCESS_DENIED");}}
}
